#!/usr/bin/env node
/*
 * run-oracle.ts — Runs the designs of oracle/designs/index.json natively
 * (gfortran binary) and stores the verified outputs in oracle/reference/.
 *
 * Execution contract (source line 776):
 *   open(unit=22,file='leparagliding.txt')  ->  the design MUST be named
 *   leparagliding.txt in the cwd; the airfoils named in section 2 are read
 *   from the cwd; outputs (DXF, lines.txt, logs) are written to the cwd.
 *   oracle/designs/<id>/ holds exactly these inputs (scripts/build-designs.ts).
 *
 * Compiled source: build/fortran/leparagliding.f, regenerated by
 * scripts/make-patched.sh. It is the SAME file as the WASM build: the oracle
 * compares two compilers on identical source. The binary is always rebuilt.
 *
 * The program also writes to ../stl and ../xflr5. Each design runs twice (a
 * and b), each run in its own tree build/oracle-runs/<design>-<a|b>/{run,stl,
 * xflr5}; if both are bit-identical (determinism), run/ and the stl/ and
 * xflr5/ outputs are copied to oracle/reference/<design>/ (stl/ and xflr5/ as
 * subdirectories) with a sha256 manifest of every file. The large outputs
 * (DXF, STL, SCAD) are then removed from the reference: only their sha256 is
 * versioned, the files stay in build/oracle-runs/<design>-a/.
 *
 * When the official archive ships its own outputs
 * (fortran/engine/original/designs/<id>/official-outputs.sha256), the reference is
 * also compared with them; official-outputs.known-diffs.tsv lists the expected
 * differences and why (file<TAB>reason).
 *
 * Usage: docker compose run --rm oracle node scripts/run-oracle.ts
 */
import { execFileSync, spawnSync } from 'node:child_process';
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { join } from 'node:path';
import { designIds, hashTree, knownDiffs, parseManifest, ROOT, sha256 } from './oracle-lib.ts';

const SRC = join(ROOT, 'build/fortran/leparagliding.f');
const BIN = join(ROOT, 'build/oracle-native/a.out');
const OUTPUTS = ['lines.txt', 'run-log.txt', 'lep-3d.dxf', 'leparagliding.dxf'];
const LARGE = /\.(dxf|stl|scad)$/;

// cp -R <src>/. <dest>. Not fs.cpSync: its native copy fails (EACCES) on the
// Docker Desktop bind mount of the checkout.
function copyTree(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src, { withFileTypes: true })) {
    if (entry.isDirectory()) copyTree(join(src, entry.name), join(dest, entry.name));
    else copyFileSync(join(src, entry.name), join(dest, entry.name));
  }
}

// Removes the directories under <dir> left empty, deepest first.
function removeEmptyDirs(dir: string): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const sub = join(dir, entry.name);
    removeEmptyDirs(sub);
    if (!readdirSync(sub).length) rmdirSync(sub);
  }
}

execFileSync(join(ROOT, 'scripts/make-patched.sh'), { stdio: 'inherit' });
const version = execFileSync('gfortran', ['-dumpfullversion'], { encoding: 'utf8' }).trim();
console.log(`native build: gfortran ${version} ${SRC}`);
mkdirSync(join(ROOT, 'build/oracle-native'), { recursive: true });
const compile = spawnSync('gfortran', ['-o', BIN, SRC], { encoding: 'utf8' });
writeFileSync(join(ROOT, 'build/oracle-native/gfortran-compile.log'), compile.stderr);
if (compile.status !== 0) process.exit(1);

let fail = false;
for (const design of designIds()) {
  console.log(`=== ${design} ===`);
  let ok = true;
  for (const k of ['a', 'b']) {
    const tree = join(ROOT, 'build/oracle-runs', `${design}-${k}`);
    const run = join(tree, 'run');
    rmSync(tree, { recursive: true, force: true });
    for (const dir of [run, join(tree, 'stl'), join(tree, 'xflr5')]) {
      mkdirSync(dir, { recursive: true }); // ../stl, ../xflr5 of the program
    }
    copyTree(join(ROOT, 'oracle/designs', design), run);
    const result = spawnSync(BIN, ['leparagliding.txt'], { cwd: run });
    writeFileSync(join(run, 'stdout.log'), result.stdout);
    writeFileSync(join(run, 'stderr.log'), result.stderr);
    console.log(`[${design}/${k}] exit=${result.status ?? result.signal}`);
    for (const name of OUTPUTS) {
      if (!existsSync(join(run, name)) || statSync(join(run, name)).size === 0) {
        console.log(`[${design}/${k}] MISSING OR EMPTY OUTPUT: ${name}`);
        ok = false;
      }
    }
  }
  if (!ok) {
    fail = true;
    continue;
  }

  const a = join(ROOT, 'build/oracle-runs', `${design}-a`);
  const hashA = hashTree(a);
  const hashB = hashTree(join(ROOT, 'build/oracle-runs', `${design}-b`));
  if (hashA !== hashB) {
    console.log(`[${design}] NOT DETERMINISTIC, run-a / run-b diff:`);
    const linesA = hashA.split('\n');
    const linesB = hashB.split('\n');
    const diff = [
      ...linesA.filter((line) => !linesB.includes(line)).map((line) => `< ${line}`),
      ...linesB.filter((line) => !linesA.includes(line)).map((line) => `> ${line}`),
    ];
    console.log(diff.slice(0, 20).join('\n'));
    fail = true;
    continue;
  }
  console.log(`[${design}] deterministic: run-a == run-b`);

  const ref = join(ROOT, 'oracle/reference', design);
  rmSync(ref, { recursive: true, force: true });
  copyTree(join(a, 'run'), ref);
  for (const sub of ['stl', 'xflr5']) {
    if (readdirSync(join(a, sub)).length) copyTree(join(a, sub), join(ref, sub));
  }
  writeFileSync(join(ref, 'MANIFEST.sha256'), hashTree(ref));
  console.log(`[${design}] reference -> oracle/reference/${design}`);

  const official = join(ROOT, 'fortran/engine/original/designs', design, 'official-outputs.sha256');
  if (existsSync(official)) {
    // file -> reason
    const tsv = official.replace(/\.sha256$/, '.known-diffs.tsv');
    const known = new Map(knownDiffs(tsv, 2).map(([file, reason]) => [file, reason]));
    for (const [name, sum] of parseManifest(readFileSync(official, 'utf8'))) {
      const reason = known.get(name);
      const file = join(ref, name);
      if (existsSync(file) && sha256(readFileSync(file)) === sum) {
        console.log(`[${design}] ${name} identical to the official output`);
        if (reason) {
          console.log(`[${design}] ${name}: remove it from official-outputs.known-diffs.tsv`);
        }
      } else if (reason) {
        console.log(`[${design}] ${name} differs from the official output (known: ${reason})`);
      } else {
        console.log(`[${design}] ${name} DIFFERS FROM THE OFFICIAL OUTPUT`);
        fail = true;
      }
    }
  }

  // Only the sha256 of the large outputs is versioned.
  for (const entry of readdirSync(ref, { recursive: true, withFileTypes: true })) {
    if (entry.isFile() && LARGE.test(entry.name)) rmSync(join(entry.parentPath, entry.name));
  }
  removeEmptyDirs(ref);
}

console.log(fail ? 'NATIVE ORACLE: FAILED' : 'NATIVE ORACLE: OK');
process.exit(fail ? 1 : 0);
